export const CATEGORIES = [
  'delivery',
  'payment',
  'refund',
  'product_quality',
  'account',
  'other',
] as const;

export type Category = (typeof CATEGORIES)[number];

export interface Message {
  message_id: string;
  category: Category;
  is_urgent: boolean;
  order_ref: string | null;
  duplicate_of: string | null;
  customer_id: string;
  channel: string;
  received_at: string | null;
  answered_at: string | null;
  subject: string;
  body: string;
  severity: 'high' | 'normal';
  severity_hint: string | null;
  label_source?: 'llm' | 'keywords';
  answered: boolean;
  group_answered_at: string | null;
  answer_time_unknown: boolean;
  sla_deadline: string | null;
  business_minutes_left: number | null;
}

export interface DataQuality {
  records_read: number;
  rows_kept: number;
  blank_rows_skipped: number;
  rows_without_id_skipped: number;
  unparseable_received_at: string[];
  missing_received_at: string[];
  unparseable_answered_at: string[];
  answered_before_received: string[];
  duplicate_message_ids: string[];
  short_rows: string[];
  rows_with_extra_fields: string[];
}

export interface Classification {
  mode: 'llm' | 'keywords';
  llm_labels?: number;
  keyword_labels?: number;
  llm_error?: string | null;
}

export interface AnalyzeResult {
  total_unique_messages: number;
  category_counts: Partial<Record<Category, number>>;
  urgent_message_ids: string[];
  messages: Message[];
  data_quality?: DataQuality;
  classification?: Classification;
}

export interface Draft {
  message_id: string;
  draft: string;
  language: 'fa' | 'en';
  blocked: boolean;
  warnings: string[];
}

import type { Category } from './types';

const CATEGORY_FA: Record<Category, string> = {
  delivery: 'ارسال و تحویل',
  payment: 'پرداخت',
  refund: 'بازگشت وجه',
  product_quality: 'کیفیت کالا',
  account: 'حساب کاربری',
  other: 'سایر',
};

export function formatCategory(cat: string): string {
  return CATEGORY_FA[cat as Category] ?? cat;
}

/** Persian digits for display; attributes for QA stay Latin. */
export function faNumber(n: number): string {
  return n.toLocaleString('fa-IR');
}

export function formatPercent(part: number, total: number): string {
  const pct = total > 0 && Number.isFinite(part) ? (part / total) * 100 : 0;
  return `${pct.toLocaleString('fa-IR', { minimumFractionDigits: 1, maximumFractionDigits: 1 })}٪`;
}

/** "۱ ساعت و ۵ دقیقه" for a number of business minutes (sign ignored). */
export function formatDuration(minutes: number): string {
  const abs = Math.abs(minutes);
  const h = Math.floor(abs / 60);
  const m = abs % 60;
  if (h && m) return `${faNumber(h)} ساعت و ${faNumber(m)} دقیقه`;
  if (h) return `${faNumber(h)} ساعت`;
  return `${faNumber(m)} دقیقه`;
}

/** Text for the countdown column. */
export function describeTimeLeft(minutes: number): string {
  if (minutes > 0) return `${formatDuration(minutes)} تا پایان مهلت`;
  if (minutes === 0) return 'مهلت همین حالا تمام شد';
  return `${formatDuration(minutes)} از مهلت گذشته`;
}

/** Tehran time, Persian calendar, for display. */
export function formatDate(iso: string | null): string {
  if (!iso) return '—';
  const d = new Date(iso);
  if (Number.isNaN(d.getTime())) return iso;
  return d.toLocaleString('fa-IR', {
    timeZone: 'Asia/Tehran', year: 'numeric', month: '2-digit', day: '2-digit',
    hour: '2-digit', minute: '2-digit',
  });
}

