import { useMemo, useState } from 'react';
import { faNumber, formatCategory, formatDate } from '../format';
import { CATEGORIES, type Message } from '../types';
import OrderText from './OrderText';

const MAX_ROWS = 200;

export default function MessagesTable({ messages }: { messages: Message[] }) {
  const [category, setCategory] = useState<string>('');
  const [query, setQuery] = useState('');

  const filtered = useMemo(() => {
    const q = query.trim().toLowerCase();
    return messages.filter((m) =>
      (!category || m.category === category)
      && (!q || `${m.message_id} ${m.order_ref ?? ''} ${m.subject} ${m.body}`.toLowerCase().includes(q)));
  }, [messages, category, query]);
  const rows = filtered.slice(0, MAX_ROWS);

  return (
    <section className="card" aria-labelledby="messages-title">
      <h2 id="messages-title">همهٔ پیام‌ها</h2>
      <div className="filters">
        <label>
          دسته
          <select value={category} onChange={(e) => setCategory(e.target.value)}>
            <option value="">همه</option>
            {CATEGORIES.map((c) => <option key={c} value={c}>{formatCategory(c)}</option>)}
          </select>
        </label>
        <label>
          جستجو
          <input type="search" value={query} onChange={(e) => setQuery(e.target.value)} placeholder="شناسه، سفارش یا متن" />
        </label>
      </div>
      {filtered.length > MAX_ROWS && (
        <p className="muted">نمایش {faNumber(MAX_ROWS)} پیام از {faNumber(filtered.length)}.</p>
      )}
      <div className="table-wrap">
        <table>
          <thead>
            <tr>
              <th>شناسه</th><th>دسته</th><th>جدی</th><th>فوری</th><th>سفارش</th>
              <th>کانال</th><th>دریافت</th><th>موضوع</th><th>متن</th>
            </tr>
          </thead>
          <tbody>
            {rows.map((m) => (
              <tr key={m.message_id} className={m.duplicate_of ? 'resend' : undefined}>
                <td dir="ltr">
                  {m.message_id}
                  {m.duplicate_of && <div className="muted small">تکرارِ <span dir="ltr">{m.duplicate_of}</span></div>}
                </td>
                <td>{formatCategory(m.category)}</td>
                <td>{m.severity === 'high' ? 'بله' : ''}</td>
                <td>{m.is_urgent ? 'بله' : ''}</td>
                <td dir="ltr">{m.order_ref ?? '—'}</td>
                <td dir="ltr">{m.channel || '—'}</td>
                <td>{formatDate(m.received_at)}</td>
                <td dir="auto">{m.subject}</td>
                <td dir="auto" className="body-cell"><OrderText text={m.body} /></td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </section>
  );
}

import { CATEGORIES, type Category } from '../types';
import { faNumber, formatCategory, formatPercent } from '../format';

interface Props {
  counts: Partial<Record<Category, number>>;
  total: number;
}

export default function CategoryBreakdown({ counts, total }: Props) {
  return (
    <section className="card" aria-labelledby="categories-title">
      <h2 id="categories-title">مشتریان با چه مشکلی درگیرند؟</h2>
      <p className="muted">بر اساس پیام‌های یکتا (پیام‌های تکراری یک بار شمرده می‌شوند).</p>
      <ul className="breakdown">
        {CATEGORIES.map((cat) => {
          const n = counts[cat] ?? 0; // a missing category is 0, never NaN
          const width = total > 0 ? (n / total) * 100 : 0;
          return (
            <li key={cat}>
              <span className="cat-name">{formatCategory(cat)}</span>
              <span className="bar"><span className="bar-fill" style={{ width: `${width}%` }} /></span>
              <span className="cat-count">{faNumber(n)}</span>
              <span className="cat-pct">{formatPercent(n, total)}</span>
            </li>
          );
        })}
      </ul>
    </section>
  );
}

import { faNumber } from '../format';

interface Props {
  total: number;
  attention: number;
  urgent: number;
  resends: number;
}

export default function SummaryTiles({ total, attention, urgent, resends }: Props) {
  return (
    <section className="tiles">
      <div className="card tile urgent" data-testid="urgent-count">
        <div className="tile-label">فوری (از مهلت ۲ ساعت کاری گذشته)</div>
        <div className="tile-value">{faNumber(urgent)}</div>
      </div>
      <div className="card tile">
        <div className="tile-label">نیازمند رسیدگی</div>
        <div className="tile-value">{faNumber(attention)}</div>
      </div>
      <div className="card tile">
        <div className="tile-label">پیام یکتا</div>
        <div className="tile-value" data-testid="total">{faNumber(total)}</div>
      </div>
      <div className="card tile">
        <div className="tile-label">پیام تکراری (یک بار شمرده شد)</div>
        <div className="tile-value">{faNumber(resends)}</div>
      </div>
    </section>
  );
}

import { useState, type FormEvent } from 'react';

interface Props {
  /** referenceTehran: optional "YYYY-MM-DDTHH:mm" in Tehran time, for replaying an old export. */
  onSubmit: (file: File, referenceTehran?: string) => void;
  loading: boolean;
}

export default function UploadForm({ onSubmit, loading }: Props) {
  const [file, setFile] = useState<File | null>(null);
  const [reference, setReference] = useState('');

  function submit(e: FormEvent) {
    e.preventDefault();
    if (file) onSubmit(file, reference || undefined);
  }

  return (
    <form className="card upload" onSubmit={submit}>
      <label>
        فایل خروجی پشتیبانی (CSV)
        <input data-testid="upload-input" type="file" accept=".csv,text/csv"
               onChange={(e) => setFile(e.target.files?.[0] ?? null)} />
      </label>
      <details className="reference">
        <summary>بازپخش یک خروجی قدیمی (اختیاری)</summary>
        <label>
          «اکنون» را این زمان در نظر بگیر (به وقت تهران)؛ شمارش معکوس از همین زمان زنده ادامه می‌یابد
          <input type="datetime-local" dir="ltr" value={reference} onChange={(e) => setReference(e.target.value)} />
        </label>
      </details>
      <button type="submit" data-testid="analyze-button" disabled={!file || loading}>
        {loading ? 'در حال تحلیل… (ممکن است تا یک دقیقه طول بکشد)' : 'تحلیل'}
      </button>
    </form>
  );
}

import type { AnalyzeResult, Draft } from './types';

/** `now` is the dashboard's current time (ISO-8601 UTC), so the server and the
 *  live countdown agree on what has been answered. */
export async function analyze(file: File, now: string): Promise<AnalyzeResult> {
  const form = new FormData();
  form.append('file', file);
  const res = await fetch(`/api/analyze?now=${encodeURIComponent(now)}`, { method: 'POST', body: form });
  if (!res.ok) {
    let detail = '';
    try {
      detail = (await res.json()).detail ?? '';
    } catch {
      /* not JSON */
    }
    throw new Error(`تحلیل ناموفق بود (${res.status})${detail ? `: ${detail}` : ''}`);
  }
  return res.json();
}

export async function requestDraft(m: {
  message_id: string;
  customer_id: string;
  subject: string;
  body: string;
}): Promise<Draft> {
  const res = await fetch('/api/draft', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(m),
  });
  if (!res.ok) throw new Error(`Draft failed (${res.status})`);
  return res.json();
}

import { useEffect, useMemo, useState } from 'react';
import { analyze } from './api';
import { buildAttention, urgentCount } from './attention';
import { faNumber } from './format';
import type { AnalyzeResult } from './types';
import UploadForm from './components/UploadForm';
import SummaryTiles from './components/SummaryTiles';
import CategoryBreakdown from './components/CategoryBreakdown';
import AttentionList from './components/AttentionList';
import MessagesTable from './components/MessagesTable';

/** The countdown refreshes this often (README: at least once a minute). No server or LLM call. */
export const REFRESH_MS = 30_000;

/** Browser time, optionally shifted to replay an old export ("now" = reference + time since upload). */
function useNow(offsetMs: number): number {
  const [now, setNow] = useState(() => Date.now() + offsetMs);
  useEffect(() => {
    const tick = () => setNow(Date.now() + offsetMs);
    tick();
    const id = setInterval(tick, REFRESH_MS);
    document.addEventListener('visibilitychange', tick);
    return () => {
      clearInterval(id);
      document.removeEventListener('visibilitychange', tick);
    };
  }, [offsetMs]);
  return now;
}

export default function App() {
  const [result, setResult] = useState<AnalyzeResult | null>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [offsetMs, setOffsetMs] = useState(0);
  const now = useNow(offsetMs);

  async function handleSubmit(file: File, referenceTehran?: string) {
    const offset = referenceTehran ? Date.parse(`${referenceTehran}:00+03:30`) - Date.now() : 0;
    setLoading(true);
    setError(null);
    try {
      const r = await analyze(file, new Date(Date.now() + offset).toISOString());
      setOffsetMs(Number.isFinite(offset) ? offset : 0);
      setResult(r);
    } catch (e) {
      setResult(null);
      setError(e instanceof Error ? e.message : String(e));
    } finally {
      setLoading(false);
    }
  }

  const attention = useMemo(() => (result ? buildAttention(result.messages, now) : null), [result, now]);
  const resends = result ? result.messages.filter((m) => m.duplicate_of !== null).length : 0;
  const dq = result?.data_quality;
  const cls = result?.classification;

  return (
    <main className="container">
      <header>
        <h1>داشبورد پشتیبانی بازارچه</h1>
        <p className="muted">خروجی روزانهٔ پیام‌های پشتیبانی را بارگذاری کنید تا ببینید مشتریان با چه مشکلی درگیرند و چه پیام‌هایی فوری است.</p>
      </header>
      <UploadForm onSubmit={handleSubmit} loading={loading} />
      {error && <p className="error" role="alert">{error}</p>}
      {result && attention && (
        <>
          {offsetMs !== 0 && (
            <p className="notice">حالت بازپخش: «اکنون» {new Date(now).toLocaleString('fa-IR', { timeZone: 'Asia/Tehran' })} به وقت تهران است.</p>
          )}
          <SummaryTiles
            total={result.total_unique_messages}
            attention={attention.items.length}
            urgent={urgentCount(attention.items)}
            resends={resends}
          />
          <AttentionList items={attention.items} unknownTime={attention.unknownTime} />
          <CategoryBreakdown counts={result.category_counts} total={result.total_unique_messages} />
          <MessagesTable messages={result.messages} />
          <footer className="muted small">
            {dq && (
              <p>
                کیفیت داده: {faNumber(dq.records_read)} ردیف خوانده شد، {faNumber(dq.rows_kept)} پیام نگه داشته شد،
                {' '}{faNumber(dq.blank_rows_skipped + dq.rows_without_id_skipped)} ردیف خالی/بدون شناسه کنار گذاشته شد
                {dq.unparseable_received_at.length > 0 && `، ${faNumber(dq.unparseable_received_at.length)} زمان دریافتِ ناخوانا`}
                {dq.answered_before_received.length > 0 && `، ${faNumber(dq.answered_before_received.length)} پاسخ با زمانی پیش از دریافت (پاسخ‌داده حساب شد)`}.
              </p>
            )}
            {cls && (
              <p>
                دسته‌بندی: {cls.mode === 'llm'
                  ? `هوش مصنوعی برای ${faNumber(cls.llm_labels ?? 0)} پیام، قواعد کلیدواژه‌ای برای ${faNumber(cls.keyword_labels ?? 0)} پیام`
                  : 'فقط قواعد کلیدواژه‌ای (هوش مصنوعی پیکربندی نشده)'}.
              </p>
            )}
          </footer>
        </>
      )}
    </main>
  );
}

